<template><view class="page"><view class="field"><text class="label">标题</text><input v-model="title" placeholder="给这条笔记起个标题" /></view><view class="field"><text class="label">分类</text><picker :range="categoryOptions" @change="pickCategory"><view class="picker">{{category}}　›</view></picker></view><view class="field"><text class="label">内容</text><textarea v-model="content" placeholder="记录此刻的想法…" maxlength="5000" /></view><view class="field"><text class="label">标签</text><input v-model="tags" placeholder="用逗号分隔，例如：灵感,阅读" /></view><view class="field publish"><text>公开分享</text><switch :checked="published" color="#536cf1" @change="published=$event.detail.value" /></view><button class="save" @click="save">保存笔记</button><text class="note">图文上传、草稿撤销和小程序链接分享将在后续版本接入。</text></view></template>
<script setup>import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';const title=ref(''),content=ref(''),category=ref('学习方法'),tags=ref(''),published=ref(false),categoryOptions=['学习方法','读书摘录','灵感','工作记录'];function pickCategory(e){category.value=categoryOptions[e.detail.value]}onLoad(()=>{});function save(){if(!title.value.trim()){uni.showToast({title:'请先填写标题',icon:'none'});return}uni.showToast({title:'演示框架暂未连接云端，内容未保存',icon:'none'})}</script>
<style scoped>.page{padding:22px 20px}.field{margin-bottom:18px;padding:15px;background:white;border-radius:14px}.label{display:block;margin-bottom:12px;font-size:13px;font-weight:600}.field input,.picker{font-size:13px;color:#525963}.field textarea{width:100%;height:220px;font-size:13px;line-height:1.8}.publish{display:flex;justify-content:space-between;align-items:center;font-size:13px}.publish switch{transform:scale(.8);transform-origin:right center}.save{margin-top:24px;background:#536cf1;color:white;border-radius:14px;font-size:14px}.note{display:block;margin-top:15px;text-align:center;color:#9da2aa;font-size:10px}</style>
